import warnings
import numpy as np
from statsmodels.stats.correlation_tools import cov_nearest


def _call(mat, **kw):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        try:
            return cov_nearest(mat, **kw)
        except TypeError:
            # min_diag unsupported at the buggy revision: fall back to the
            # documented default call, which is exactly the reported bug.
            return cov_nearest(mat, method=kw.get("method", "clipped"))


def _report(tag, mat):
    res = _call(mat, method="clipped", min_diag=1e-8)
    res = np.asarray(res, dtype=float)
    diag = np.diag(res)
    probe(tag + "_diag0", float(diag[0]))
    probe(tag + "_diag1", float(diag[1]))
    probe(tag + "_n_nan", float(np.isnan(res).sum()))
    try:
        mineig = float(np.linalg.eigvalsh(res).min())
    except Exception:
        mineig = float("nan")
    probe(tag + "_min_eig", mineig)


_report("zero", np.array([[2.0, 0.0], [0.0, 0.0]]))
_report("neg", np.array([[2.0, 0.0], [0.0, -1e-8]]))

